+
+      .choice input {
+        margin-top: 2px;
+        width: 18px;
+        height: 18px;
+        accent-color: var(--accent);
+      }
+
+      .choice span {
+        line-height: 1.4;
+      }
+
+      .actions {
+        display: flex;
+        justify-content: flex-end;
+        margin-top: 22px;
+      }
+
+      button {
+        appearance: none;
+        border: 0;
+        border-radius: 999px;
+        padding: 14px 22px;
+        font: inherit;
+        font-weight: 700;
+        color: white;
+        background: linear-gradient(135deg, var(--accent), #5f6bff);
+        box-shadow: 0 12px 30px rgba(95, 107, 255, 0.35);
+        cursor: pointer;
+      }
+
+      button:hover {
+        filter: brightness(1.05);
+      }
+
+      .result {
+        margin-top: 16px;
+        color: var(--muted);
+        font-size: 0.95rem;
