        --panel: #11182b;
        --panel-2: #151f38;
        --text: #e8eefc;
        --muted: #9aa8c7;
        --border: rgba(148, 163, 184, 0.18);
        --accent: #7c8cff;
        --accent-2: #66e0c5;
        --shadow: 0 24px 70px rgba(0, 0, 0, 0.45);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(124, 140, 255, 0.22), transparent 34%),
