        width: min(760px, 100%);
        background: linear-gradient(180deg, rgba(21, 31, 56, 0.96), rgba(12, 18, 35, 0.98));
        border: 1px solid var(--border);
        border-radius: 24px;
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .quiz-header {
        padding: 28px 28px 18px;
        border-bottom: 1px solid var(--border);
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), transparent);
      }

      .eyebrow {
        margin: 0 0 10px;
        color: var(--accent-2);
        text-transform: uppercase;
        letter-spacing: 0.14em;
        font-size: 0.78rem;
        font-weight: 700;
      }

      h1 {
        margin: 0;
        font-size: clamp(1.7rem, 2.8vw, 2.4rem);
        line-height: 1.1;
      }

      .subtitle {
        margin: 10px 0 0;
        color: var(--muted);
        max-width: 62ch;
      }

      form {
        padding: 24px 28px 28px;
      }

      .form-field {
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.015));
        border: 1px solid var(--border);
        border-radius: 18px;
        padding: 20px;
        margin-bottom: 18px;
      }

      .question-row {
        display: flex;
        align-items: start;
        gap: 12px;
        justify-content: space-between;
        margin-bottom: 14px;
      }

      .question-title {
        margin: 0;
        font-size: 1.05rem;
      }

      .help-text {
        margin: 8px 0 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .choices {
        display: grid;
        gap: 12px;
      }

      .choice {
        display: flex;
        gap: 12px;
        align-items: flex-start;
        padding: 14px 14px 14px 12px;
        border: 1px solid rgba(148, 163, 184, 0.14);
        border-radius: 14px;
        background: rgba(255, 255, 255, 0.02);
        transition: transform 0.15s ease, border-color 0.15s ease, background 0.15s ease;
      }

      .choice:hover {
        transform: translateY(-1px);
        border-color: rgba(124, 140, 255, 0.4);
        background: rgba(124, 140, 255, 0.08);
      }

      .choice input {
        margin-top: 2px;
        width: 18px;
        height: 18px;
        accent-color: var(--accent);
      }

      .choice span {
        line-height: 1.4;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        margin-top: 22px;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        font: inherit;
        font-weight: 700;
        color: white;
        background: linear-gradient(135deg, var(--accent), #5f6bff);
        box-shadow: 0 12px 30px rgba(95, 107, 255, 0.35);
        cursor: pointer;
      }

      button:hover {
        filter: brightness(1.05);
      }

      .result {
        margin-top: 16px;
        color: var(--muted);
        font-size: 0.95rem;
      }

      @media (max-width: 640px) {
        .quiz-header,
        form {
          padding-left: 18px;
          padding-right: 18px;
        }

        .form-field {
          padding: 16px;
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>

    <script>
      const questions = [
        {
          id: "q1",
          title: "Which of these are programming languages?",
          helpText: "Select every option that is used to write software.",
          choices: [
            "Python",
            "JavaScript",
            "HTML",
            "Rust",
          ],
        },
        {
          id: "q2",
          title: "Which are commonly used for web development?",
          choices: [
            "TypeScript",
            "C++",
            "CSS",
            "Ruby",
          ],
        },
        {
          id: "q3",
          title: "Which are considered low-level or system-oriented languages?",
          choices: [
            "Assembly",
            "C",
            "SQL",
            "Go",
          ],
        },
      ];

      function Choice({ questionId, label, index }) {
        const inputId = `${questionId}-${index}`;
        return `
          <label class="choice" for="${inputId}">
            <input id="${inputId}" name="${questionId}" type="checkbox" />
            <span>${label}</span>
          </label>
        `;
      }

      function Question({ id, title, helpText, choices }) {
        return `
          <div class="form-field">
            <div class="question-row">
              <div>
                <h2 class="question-title">${title}</h2>
                ${helpText ? `<p class="help-text">${helpText}</p>` : ""}
              </div>
            </div>
            <div class="choices">
              ${choices.map((choice, index) => Choice({ questionId: id, label: choice, index })).join("")}
            </div>
          </div>
        `;
      }

      function App() {
        return `
          <main class="quiz-shell">
            <header class="quiz-header">
              <p class="eyebrow">Multiple-select quiz</p>
              <h1>Computer Languages Quiz</h1>
              <p class="subtitle">Choose all answers that apply for each question.</p>
            </header>
            <form id="quiz-form">
              ${questions.map((question) => Question(question)).join("")}
              <div class="actions">
                <button type="submit">Submit</button>
              </div>
              <p class="result" id="result" aria-live="polite"></p>
            </form>
          </main>
        `;
      }

      document.getElementById("root").innerHTML = App();

      document.getElementById("quiz-form").addEventListener("submit", function (event) {
        event.preventDefault();
        document.getElementById("result").textContent = "Submitted. Thanks for taking the quiz!";
      });
    </script>
  </body>
</html>
