         form {
           padding-left: 18px;
           padding-right: 18px;
         }

         .form-field {
           padding: 16px;
         }
       }
     </style>
   </head>
   <body>
     <div id="root"></div>

     <script>
       const questions = [
         {
           id: "q1",
           title: "Which of these are programming languages?",
           helpText: "Select every option that is used to write software.",
           choices: [
             "Python",
             "JavaScript",
             "HTML",
             "Rust",
           ],
         },
         {
           id: "q2",
           title: "Which are commonly used for web development?",
           choices: [
             "TypeScript",
             "C++",
             "CSS",
             "Ruby",
           ],
         },
         {
           id: "q3",
           title: "Which are considered low-level or system-oriented languages?",
           choices: [
             "Assembly",
             "C",
             "SQL",
             "Go",
           ],
         },
       ];

       function Choice({ questionId, label, index }) {
         const inputId = `${questionId}-${index}`;
         return `
           <label class="choice" for="${inputId}">
             <input id="${inputId}" name="${questionId}" type="checkbox" />
             <span>${label}</span>
           </label>
         `;
       }

       function Question({ id, title, helpText, choices }) {
         return `
           <div class="form-field">
             <div class="question-row">
               <div>
                 <h2 class="question-title">${title}</h2>
                 ${helpText ? `<p class="help-text">${helpText}</p>` : ""}
               </div>
             </div>
             <div class="choices">
               ${choices.map((choice, index) => Choice({ questionId: id, label: choice, index })).join("")}
             </div>
           </div>
         `;
       }

       function App() {
         return `
           <main class="quiz-shell">
             <header class="quiz-header">
               <p class="eyebrow">Multiple-select quiz</p>
               <h1>Computer Languages Quiz</h1>
               <p class="subtitle">Choose all answers that apply for each question.</p>
             </header>
             <form id="quiz-form">
               ${questions.map((question) => Question(question)).join("")}
               <div class="actions">
                 <button type="submit">Submit</button>
               </div>
               <p class="result" id="result" aria-live="polite"></p>
             </form>
           </main>
         `;
       }

       document.getElementById("root").innerHTML = App();

       document.getElementById("quiz-form").addEventListener("submit", function (event) {
         event.preventDefault();
         document.getElementById("result").textContent = "Submitted. Thanks for taking the quiz!";
       });
     </script>
   </body>
 </html>

')
